SELECT DISTINCT line_id FROM DAILY_APP_TOTAL_DATA WHERE deleted_at IS NULL AND (
(usage_date >= #{targetMonthStart} AND usage_date < DATE_ADD(#{targetMonthStart}, INTERVAL 1 MONTH))
)

SELECT DISTINCT line_id
FROM TRAFFIC_DEDUCT_DONE
WHERE enqueued_at >= #{startInclusive}
  AND enqueued_at < #{endExclusive}
